import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BgSoyxN5.js";const h=JSON.parse('{"title":"Privacy Policy","description":"TickerForge Privacy Policy covering website analytics, widgets, email leads, Telegram continuation, portfolio diagnostics, payment metadata, and cookies.","frontmatter":{"title":"Privacy Policy","description":"TickerForge Privacy Policy covering website analytics, widgets, email leads, Telegram continuation, portfolio diagnostics, payment metadata, and cookies."},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1783339004000}'),i={name:"privacy.md"};function n(s,e,l,d,c,p){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><em>Last updated: 05 July 2026</em></p><p>This Privacy Policy explains how <strong>TickerForge</strong> collects, uses, and protects data when you use the website, widgets, Telegram bot workflows, product emails, paid subscriptions, and related services.</p><p>TickerForge is operated by <strong>Anton Tkach</strong>, trading as <strong>TickerForge</strong>.</p><p>Contact: <strong><a href="mailto:privacy@ticker-forge.com" target="_blank" rel="noreferrer">privacy@ticker-forge.com</a></strong></p><h2 id="_1-what-we-collect" tabindex="-1">1. What We Collect <a class="header-anchor" href="#_1-what-we-collect" aria-label="Permalink to &quot;1. What We Collect&quot;">​</a></h2><p>We collect data needed to run TickerForge, improve product workflows, and provide requested follow-up.</p><h3 id="data-you-provide" tabindex="-1">Data You Provide <a class="header-anchor" href="#data-you-provide" aria-label="Permalink to &quot;Data You Provide&quot;">​</a></h3><ul><li>Email address when you request product updates, reports, or support.</li><li>Product intent, such as the stock, portfolio, screener, or market workflow you selected.</li><li>Tickers, holdings, cash amounts, or portfolio summaries that you explicitly submit to a widget or bot workflow.</li><li>Support messages or feedback you choose to send.</li></ul><h3 id="website-and-widget-data" tabindex="-1">Website and Widget Data <a class="header-anchor" href="#website-and-widget-data" aria-label="Permalink to &quot;Website and Widget Data&quot;">​</a></h3><p>We may collect:</p><ul><li>anonymous user id and session id;</li><li>page path, source page, referrer, and UTM parameters;</li><li>widget usage events such as widget view, widget start, stock report viewed, portfolio report viewed, intent selected, email submitted, Telegram continuation clicked, article CTA clicks, internal link clicks, pricing CTA clicks, and scroll depth;</li><li>plan context and product path, such as Free, Standard payment interest, or Pro payment interest;</li><li>ticker or widget type when needed to understand product usage.</li></ul><h3 id="telegram-connection-data" tabindex="-1">Telegram Connection Data <a class="header-anchor" href="#telegram-connection-data" aria-label="Permalink to &quot;Telegram Connection Data&quot;">​</a></h3><p>If you continue from the website to Telegram, we may store Telegram continuation/linking identifiers, selected intent, timestamps, and the Telegram account information made available by Telegram. We use this to connect the web request to the bot flow you opened.</p><h3 id="payment-metadata" tabindex="-1">Payment Metadata <a class="header-anchor" href="#payment-metadata" aria-label="Permalink to &quot;Payment Metadata&quot;">​</a></h3><p>When payments are enabled, we may store limited payment metadata from a payment processor, reseller, merchant-of-record provider, or Telegram Stars flow, such as plan tier, subscription status, customer or subscription identifiers, payment status, renewal/cancellation timestamps, and checkout event metadata needed for access control and support.</p><p>TickerForge does not store card numbers.</p><h2 id="_2-what-we-do-not-send-to-ga4-or-meta" tabindex="-1">2. What We Do Not Send to GA4 or Meta <a class="header-anchor" href="#_2-what-we-do-not-send-to-ga4-or-meta" aria-label="Permalink to &quot;2. What We Do Not Send to GA4 or Meta&quot;">​</a></h2><p>TickerForge does not send the following to Google Analytics, Meta Pixel, or advertising analytics:</p><ul><li>email addresses;</li><li>raw Telegram IDs;</li><li>raw portfolio holdings;</li><li>raw private prompts or free-form private inputs;</li><li>raw continuation codes;</li><li>broker credentials, account numbers, or identity documents.</li></ul><p>Analytics events use aggregate or limited product metadata such as event names, page paths, widget type, selected intent category, plan context, and UTM values.</p><h2 id="_3-cookies-ga4-and-meta-pixel" tabindex="-1">3. Cookies, GA4, and Meta Pixel <a class="header-anchor" href="#_3-cookies-ga4-and-meta-pixel" aria-label="Permalink to &quot;3. Cookies, GA4, and Meta Pixel&quot;">​</a></h2><p>TickerForge uses a cookie/analytics consent banner. Optional Google Analytics and Meta Pixel tracking should run only after consent where required.</p><p>These tools help us understand site usage, campaign performance, widget interactions, and product funnels. You can accept or reject optional analytics from the cookie banner.</p><h2 id="_4-product-email" tabindex="-1">4. Product Email <a class="header-anchor" href="#_4-product-email" aria-label="Permalink to &quot;4. Product Email&quot;">​</a></h2><p>TickerForge may use <strong>Resend</strong> to send product emails, such as report-ready messages, smart alert updates, product follow-up, or support replies.</p><p>Email is used for the purpose requested by the user or for product communications related to that request. We do not sell email addresses.</p><h2 id="_5-payments" tabindex="-1">5. Payments <a class="header-anchor" href="#_5-payments" aria-label="Permalink to &quot;5. Payments&quot;">​</a></h2><p>When payments are enabled, a third-party payment processor, reseller, merchant-of-record provider, or platform payment flow may process payment, tax, invoicing, subscription management, and refund-related data. That provider&#39;s own policies may also apply to checkout and payment handling.</p><p>TickerForge stores only the limited payment metadata needed to provide access, support billing, and reconcile subscription status.</p><h2 id="_6-portfolio-and-widget-inputs" tabindex="-1">6. Portfolio and Widget Inputs <a class="header-anchor" href="#_6-portfolio-and-widget-inputs" aria-label="Permalink to &quot;6. Portfolio and Widget Inputs&quot;">​</a></h2><p>If you enter holdings, cash, or portfolio data, TickerForge uses it to generate diagnostics, snapshots, risk checks, stress tests, and related software outputs.</p><p>We do not request broker login credentials, account passwords, identity documents, or full brokerage statements in the browser widget flow.</p><h2 id="_7-how-we-use-data" tabindex="-1">7. How We Use Data <a class="header-anchor" href="#_7-how-we-use-data" aria-label="Permalink to &quot;7. How We Use Data&quot;">​</a></h2><p>We use collected data to:</p><ul><li>provide software analytics, diagnostics, monitoring, and reports;</li><li>send requested product emails or Telegram continuation flows;</li><li>operate subscriptions and paid access;</li><li>improve website, widget, and bot workflows;</li><li>detect abuse, debug errors, and maintain security;</li><li>measure campaign and product funnel performance, subject to consent where required;</li><li>respond to support requests.</li></ul><h2 id="_8-sharing" tabindex="-1">8. Sharing <a class="header-anchor" href="#_8-sharing" aria-label="Permalink to &quot;8. Sharing&quot;">​</a></h2><p>We may share data with service providers needed to operate TickerForge, including hosting providers, database providers, Telegram, Resend, payment processors, Google Analytics, Meta Pixel, and internal analytics/reporting tools.</p><p>We do not sell personal data.</p><h2 id="_9-retention" tabindex="-1">9. Retention <a class="header-anchor" href="#_9-retention" aria-label="Permalink to &quot;9. Retention&quot;">​</a></h2><p>We keep data only as long as needed for product operation, support, security, analytics, legal compliance, or subscription management.</p><p>Portfolio and monitoring data may be kept until deleted, replaced, expired, or no longer needed for the feature. Operational logs may be retained for debugging and security.</p><h2 id="_10-your-rights" tabindex="-1">10. Your Rights <a class="header-anchor" href="#_10-your-rights" aria-label="Permalink to &quot;10. Your Rights&quot;">​</a></h2><p>Depending on your jurisdiction, you may have rights to access, correct, delete, restrict, object to processing, export data, or withdraw consent.</p><p>To make a request, contact: <strong><a href="mailto:privacy@ticker-forge.com" target="_blank" rel="noreferrer">privacy@ticker-forge.com</a></strong></p><h2 id="_11-security" tabindex="-1">11. Security <a class="header-anchor" href="#_11-security" aria-label="Permalink to &quot;11. Security&quot;">​</a></h2><p>We use reasonable technical and organizational safeguards, including access controls, data minimization, and operational monitoring. No system can be guaranteed 100% secure.</p><h2 id="_12-children" tabindex="-1">12. Children <a class="header-anchor" href="#_12-children" aria-label="Permalink to &quot;12. Children&quot;">​</a></h2><p>TickerForge is not intended for children under 16. We do not knowingly collect data from children under 16.</p><h2 id="_13-changes" tabindex="-1">13. Changes <a class="header-anchor" href="#_13-changes" aria-label="Permalink to &quot;13. Changes&quot;">​</a></h2><p>We may update this Privacy Policy from time to time. The updated version will be posted on this page.</p><h2 id="_14-contact" tabindex="-1">14. Contact <a class="header-anchor" href="#_14-contact" aria-label="Permalink to &quot;14. Contact&quot;">​</a></h2><p>Privacy questions: <strong><a href="mailto:privacy@ticker-forge.com" target="_blank" rel="noreferrer">privacy@ticker-forge.com</a></strong></p>',53)]))}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
